from core.rules import RuleMachine


class EqualTopFrontierMerge:
    """Mueve a una pila ordenada no vacía con el mismo grupo en la cima, desde una fuente ordenada o casi ordenada."""

    name = "equal_top_frontier_merge"

    def __init__(self, max_misplaced_on_source=1):
        self.max_misplaced_on_source = max_misplaced_on_source

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so = a.so
            sd = a.sd

            hs = partial.h(so)
            hd = partial.h(sd)
            if hs <= 0 or hd <= 0:
                continue

            moved_group = partial.g(so)
            dest_top = partial.g(sd)
            if moved_group != dest_top:
                continue

            if not partial.is_sorted_stack(sd):
                continue

            misplaced = hs - partial.sorted_n[so]
            if misplaced < 0 or misplaced > self.max_misplaced_on_source:
                continue

            allowed.append(a)
        return allowed


def build_component(problem, **params):
    max_misplaced_on_source = params.get("max_misplaced_on_source", 1)
    return RuleMachine(problem, [EqualTopFrontierMerge(max_misplaced_on_source=max_misplaced_on_source)])
